# shellcheck shell=bash
#
# ОДНА ДВЕРЬ PUSH'А В `comms` ДЛЯ ВСЕХ ПИСАТЕЛЕЙ КОНТУРА (тред 042-notifier-down).
#
# Повод — живой отказ 2026-08-07, прогон 31177540774 (`CI Outcome`, джоба
# `deliver`): пять попыток за 18 секунд, каждая отклонена, и в лог пять раз
# напечатано «в comms писали параллельно». Параллельно НЕ писали: между
# попытками `git fetch` привозил одну и ту же голову `52a635dd`, то есть
# пересборка поверх свежего origin/comms лечила не ту болезнь. Удалённая
# сторона говорила другое:
#
#     remote: fatal error in commit_refs
#      ! [remote rejected]       HEAD -> comms (failure)
#
# Это отказ СЕРВЕРА, а не гонка. У двух отказов разные лекарства, и до сих пор
# ни одно из них не применялось правильно:
#   * ГОНКА (`! [rejected] … (fetch first|non-fast-forward)`) лечится
#     пересборкой поверх свежей головы — она и была написана, и она верна;
#   * ОТКАЗ СЕРВЕРА лечится ОЖИДАНИЕМ. Пересборка ему безразлична, а пять
#     мгновенных повторов укладываются в 18 секунд — окно, которого хватает
#     ровно на то, чтобы не пережить хиккап и объявить доставку потерянной.
#
# Поэтому здесь две вещи, которых не было:
#   1. ПРИЧИНА ОТКАЗА НАЗЫВАЕТСЯ ПО ФАКТУ, а не по догадке: stderr push'а
#      печатается целиком и классифицируется. Диагноз в логе, разошедшийся с
#      тем, что сказала удалённая сторона, стоил разбора вручную;
#   2. ПАУЗА, РАСТУЩАЯ С НОМЕРОМ ПОПЫТКИ, и только для отказа сервера: гонке
#      ждать незачем (её лекарство — пересборка), серверу — только и остаётся.
#      Шесть попыток с паузами 10/20/30/40/50 с накрывают ~2.5 минуты вместо
#      прежних 18 секунд.
#
# Файл ИМЕННО ОДИН на пятерых писателей (`ci-outcome`, `notifier-watch`,
# `merge-notify`, `comms-derived`, `claude-review`): цикл был скопирован в
# каждого, и вместе с ним копировался неверный диагноз. Правка в пяти местах
# — это правка, которую забудут в одном из пяти.
#
# ПОДКЛЮЧАЮТСЯ ПИСАТЕЛИ НЕ ЭТИМ PR, И ПОРЯДОК ЗДЕСЬ ВЫНУЖДЕННЫЙ, А НЕ
# ОСТОРОЖНЫЙ. Шагов ровно три:
#   1. дверь ложится на main (ЭТОТ PR) — сама по себе она no-op: пока её никто
#      не подключил `source`'ом, поведение контура не меняется ни на байт;
#   2. четверо писателей, исполняющихся ИЗ main (`ci-outcome`, `notifier-watch`,
#      `merge-notify`, `claude-review`), переводятся на неё следующим PR —
#      диффом в `.github/workflows/**` и только им;
#   3. пятый (`comms-derived`) — после них: копия в `comms`, затем канон.
# Шаг 3 отделён потому, что `comms-derived.yml` исполняется из ветки `comms`, а
# не из main, поэтому его канон в main обязан совпадать байт-в-байт с копией в
# `comms` (шаг «comms-derived синхронен с каноном» в `ci.yml`), и норма требует
# класть копию в `comms` ДО merge'а канонической правки. Но копия подключает
# этот файл `source`'ом из чекаута main (`.code`) — до merge'а его там ещё нет,
# и первый же push в `comms` уронил бы `derive` на отсутствующем файле. Прогон
# 31178204250 — тот самый красный шаг, на котором это вскрылось.
# Шаг 2 отделён от шага 1 по правилу №14 (норма curator 2026-07-26): гард
# claude-code-action пропускает своё ревью на любом PR, где файл воркфлоу
# отличается от версии дефолтной ветки, — а вся логика пакета (классификатор,
# паузы, 11 проверок) лежит здесь, вне `workflows/**`, и ревью ей полагается.
#
# Подключается через `source` из чекаута main (`.code`), потому что рабочая
# директория у писателей разная (у одних это ветка `comms`, у другого — PR).
#
# ИСПОЛЬЗОВАНИЕ:
#   source "${GITHUB_WORKSPACE}/.code/.github/scripts/comms-push.sh"
#   for attempt in $(seq 1 "$COMMS_PUSH_ATTEMPTS"); do
#     ... собрать запись поверх свежего origin/comms, закоммитить ...
#     comms_push "$attempt" && exit 0
#   done
#
# Настройки — переменными окружения, обе необязательные:
#   COMMS_PUSH_DIR     — рабочее дерево, откуда пушим (по умолчанию текущее);
#   COMMS_PUSH_REMOTE  — remote (по умолчанию `origin`; claude-review передаёт
#                        URL с токеном, потому что пушит из worktree).

# Потолок попыток объявлен ЗДЕСЬ и читается циклами: число в пяти местах
# разъезжается, а в сообщении «за N попыток» обязано совпадать с фактом.
COMMS_PUSH_ATTEMPTS=6

# Возвращает 0 — доставлено; 1 — не доставлено, причина напечатана, пауза
# (если она нужна этому классу отказа) уже выждана внутри.
comms_push() {
  local attempt="${1:?comms_push: не назван номер попытки}"
  local -a git_cmd=(git)
  if [ -n "${COMMS_PUSH_DIR:-}" ]; then
    git_cmd+=(-C "$COMMS_PUSH_DIR")
  fi

  local err
  # stderr — в захват, stdout — в /dev/null: нас интересует ровно то, что
  # сказала удалённая сторона, и порядок редиректов здесь значащий.
  if err="$("${git_cmd[@]}" push "${COMMS_PUSH_REMOTE:-origin}" HEAD:comms 2>&1 >/dev/null)"; then
    return 0
  fi

  # Печатаем дословно: диагноз ниже — вывод, а не замена показаниям.
  printf '%s\n' "$err"

  local wait_sec reason
  if printf '%s' "$err" | grep -qE '! \[rejected\]'; then
    # Гонка: голова уехала. Лекарство — пересборка вызывающей стороной,
    # ждать нечего, но и молотить вплотную незачем.
    reason="гонка за голову comms (в почту писали параллельно) — пересобираю"
    wait_sec=1
  elif printf '%s' "$err" | grep -qE '! \[remote rejected\]|remote: fatal|remote error|error: RPC failed|The requested URL returned error'; then
    reason="ОТКАЗ УДАЛЁННОЙ СТОРОНЫ (не гонка) — жду и повторяю"
    wait_sec=$(( attempt * 10 ))
  else
    # Неопознанное лечим как отказ сервера: ждать безопаснее, чем считать
    # гонкой то, чего мы не прочитали.
    reason="push не прошёл, причина не опознана — жду и повторяю"
    wait_sec=$(( attempt * 10 ))
  fi

  echo "::warning::push в comms отклонён (попытка ${attempt}/${COMMS_PUSH_ATTEMPTS}): ${reason}."
  echo "Push отклонён (попытка ${attempt}/${COMMS_PUSH_ATTEMPTS}) — ${reason} (пауза ${wait_sec} с)."
  sleep "$wait_sec"
  return 1
}
